"""Record-count intersection with shared budgets, including normalized self-export."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__recordFrontier=()=>{__townTest.reset('settlement',42);__townTest.step(30);__inactivePersonCodec.enable(true);hydrateSave(archivePayload());const base=archivePayload(),logical=JSON.parse(archiveLogicalPayload()),rows=[];
 for(const kind of ['people','households','firms'])for(const delta of [-1,0,1]){const lim=kind==='people'?INACTIVE_CODEC_LIMITS.total:INACTIVE_CODEC_LIMITS.entityTotal,total=lim+delta,all=JSON.parse(JSON.stringify(logical[kind]));while(all.length<total){const id=all.length;all.push(kind==='people'?{id,name:'Historical',age:96,hh:0,job:-1,deceased:true,last:[]}:kind==='households'?{id,name:'Estate',people:[],home:-1,cash:0,deposits:{},last:[]}:{id,name:'Retired',building:-1,kind:'grocer',closed:true,demolished:true,cash:0,stock:{},jobs:0,workers:[],wage:30,price:5,owner:-1,history:[]});}const wire=JSON.parse(base);
 if(kind==='people'){const history=all.filter(p=>p.deceased||p.movedAway),fields=[...new Set(history.flatMap(p=>Object.keys(p).filter(k=>k!=='id')))].sort();wire.payload.people=all.filter(p=>!p.deceased&&!p.movedAway);wire.inactive={total,fields,rows:history.map(p=>{const indices=fields.map((k,i)=>owns(p,k)?i:-1).filter(i=>i>=0);return [p.id,indices,indices.map(i=>p[fields[i]])];})};}else{const history=all.filter(r=>historicalEntity(kind,r)),fields=[...new Set(history.flatMap(r=>Object.keys(r).filter(k=>k!=='id')))].sort();wire.payload[kind]=all.filter(r=>!historicalEntity(kind,r));wire.entities[kind]={total,fields,rows:history.map(r=>{const indices=fields.map((k,i)=>owns(r,k)?i:-1).filter(i=>i>=0);return [r.id,indices,indices.map(i=>r[fields[i]])];})};}
 const before=archiveLogicalPayload(),rng=rngState,epoch=saveEpoch,accepted=hydrateSave(wire);if(accepted!==(delta<=0))throw Error('Unexpected record frontier '+kind+' '+delta);let selfExportable=false;if(accepted){const own=archivePayload();selfExportable=hydrateSave(own);if(!selfExportable)throw Error('Normalized world not self-exportable '+kind);}else if(archiveLogicalPayload()!==before||rngState!==rng||saveEpoch!==epoch)throw Error('Record rejection non-atomic');rows.push({kind,delta,total,accepted,selfExportable});}
 return rows;};
'''
with sync_playwright()as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();r=p.evaluate('__recordFrontier()');b.close()
out=ROOT/'reports/capacity-status';out.mkdir(exist_ok=True);(out/'record-frontier.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'recordFrontier':r},indent=2)+'\n');print('PASS',r)
